final StringBuilder stmt = new StringBuilder("DELETE WHERE { ");

if (!namedGraph.isEmpty()) {
    stmt.append("GRAPH ");
    stmt.append("<" + encode(namedGraph) + ">");
    stmt.append(" { ");
}

stmt.append("<" + encode(subject) + ">");
stmt.append(" ?p ?o ");

if (!namedGraph.isEmpty()) {
    stmt.append("} ");
}

stmt.append("}");
return stmt.toString();

DELETE { ?s ?p ?o }
WHERE {
  {
    <fedora-object-uri> ?p ?o .
    BIND (<fedora-object-uri> as ?s)
  } UNION {
    ?s ?p ?o
    FILTER (strstarts(str(?s), 'fedora-object-uri#'))   
  }
}
